--
-- Name: transactions trg_sync_account_balance; Type: TRIGGER; Schema: public; Owner: financeos
--

CREATE TRIGGER trg_sync_account_balance AFTER INSERT OR DELETE OR UPDATE ON public.transactions FOR EACH ROW EXECUTE FUNCTION public.sync_account_balance();


--
-- Name: transactions trg_transactions_balance_delete; Type: TRIGGER; Schema: public; Owner: financeos
--

CREATE TRIGGER trg_transactions_balance_delete AFTER DELETE ON public.transactions FOR EACH ROW WHEN ((old.type = ANY (ARRAY['income'::public.transactions_type_enum, 'expense'::public.transactions_type_enum]))) EXECUTE FUNCTION public.sync_account_balance();


--
-- Name: transactions trg_transactions_balance_insert; Type: TRIGGER; Schema: public; Owner: financeos
--

CREATE TRIGGER trg_transactions_balance_insert AFTER INSERT ON public.transactions FOR EACH ROW WHEN ((new.type = ANY (ARRAY['income'::public.transactions_type_enum, 'expense'::public.transactions_type_enum]))) EXECUTE FUNCTION public.sync_account_balance();


--
-- Name: transactions trg_transactions_balance_update; Type: TRIGGER; Schema: public; Owner: financeos
--

CREATE TRIGGER trg_transactions_balance_update AFTER UPDATE ON public.transactions FOR EACH ROW WHEN (((old.type = ANY (ARRAY['income'::public.transactions_type_enum, 'expense'::public.transactions_type_enum])) OR (new.type = ANY (ARRAY['income'::public.transactions_type_enum, 'expense'::public.transactions_type_enum])))) EXECUTE FUNCTION public.sync_account_balance();


